import{_ as e,c as o,o as t,a4 as r}from"./chunks/framework.BYxathSa.js";const x=JSON.parse('{"title":"Q10：移动端 1px 边框为什么会变粗？如何解决？","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/q10.md","filePath":"frontend/q10.md","lastUpdated":null}'),d={name:"frontend/q10.md"},c=r('<h1 id="q10-移动端-1px-边框为什么会变粗-如何解决" tabindex="-1">Q10：移动端 1px 边框为什么会变粗？如何解决？ <a class="header-anchor" href="#q10-移动端-1px-边框为什么会变粗-如何解决" aria-label="Permalink to &quot;Q10：移动端 1px 边框为什么会变粗？如何解决？&quot;">​</a></h1><p><strong>问题原因</strong>：<br> 在高清屏（Retina）下，<code>window.devicePixelRatio &gt; 1</code>（比如 DPR=2）。意味着 1 个 CSS 像素会用 2×2 个物理像素来渲染。当设置 <code>border: 1px</code> 时，实际显示的是 2 个物理像素的宽度，所以看起来边框更粗。</p><p><strong>常见解决方案</strong>：</p><ol><li><strong>伪元素 + <code>transform: scale</code>（最常用）</strong><br> 为元素添加伪元素 <code>::after</code>，设为 <code>border: 1px</code>，然后通过 <code>transform: scale(0.5)</code> 缩放（当 DPR=2 时），并以 <code>transform-origin</code> 调整位置。此方法兼容性好且简单。</li><li><strong>Viewport 的 <code>initial-scale</code></strong><br> 在 meta 标签中，根据 DPR 设置 <code>initial-scale=0.5</code>、<code>maximum-scale=0.5</code>，并配合 CSS 写 <code>1px</code>。但全局缩放会影响整个页面，可能干扰其他布局。</li><li><strong>图片实现</strong><br> 用 <code>border-image</code> 或 <code>background-image</code> 引入半透明线条。缺点是颜色修改不便。</li><li><strong>使用 <code>box-shadow</code> 模拟</strong><br><code>box-shadow: 0 0 0 0.5px #000</code>，但半像素渲染在不同浏览器上表现有差异。</li></ol>',4),a=[c];function n(s,i,l,_,p,m){return t(),o("div",null,a)}const f=e(d,[["render",n]]);export{x as __pageData,f as default};
